    internal static Cue Refine(string clip,Cue original)
    {
        if(!variants.TryGetValue(clip,out var specific)) return original;
        // Context-sensitive local feedback and existing special events always win.
        return original==Cue.Creature || original==Basis(specific) ? specific : original;
    }
    internal static bool TryBase(string clip,out Cue cue)
    { if(variants.TryGetValue(clip,out var specific)) { cue=Basis(specific); return true; } cue=Cue.Creature; return false; }
